mapper.select:
SELECT * FROM case_info


        AND patient_name LIKE '%' || #{patientName} || '%'


        AND main_index LIKE '%' || #{mainIndex} || '%'


        AND gender = #{gender}


        AND district LIKE '%' || #{district} || '%'


        AND case_type = #{caseType}


        AND syndrome_type = #{syndromeType}


        AND age >= #{ageMin}


        AND age <= #{ageMax}


        AND discover_type = #{discoverType}


        AND risk_level = #{riskLevel}


        AND report_date >= date('now', '-' || #{days} || ' days')


        AND is_severe = #{isSevere}


        AND is_death = #{isDeath}


ORDER BY report_date DESC

SELECT COUNT(*) FROM case_info


        AND patient_name LIKE '%' || #{patientName} || '%'


        AND syndrome_type = #{syndromeType}


        AND district = #{district}


        AND report_date >= date('now', '-' || #{days} || ' days')


        AND risk_level = #{riskLevel}


        AND is_severe = #{isSevere}


        AND is_death = #{isDeath}

SELECT * FROM case_info WHERE is_severe = 1

    AND syndrome_type = #{syndromeType}

ORDER BY report_date DESC

SELECT * FROM case_info WHERE is_death = 1

    AND syndrome_type = #{syndromeType}

ORDER BY report_date DESC

choose.when:
SELECT strftime('%Y-W%W', report_date) as period, COUNT(*) as cnt
FROM case_info


        AND syndrome_type = #{syndromeType}


        AND district = #{district}


        AND report_date >= date('now', '-' || #{days} || ' days')


GROUP BY period ORDER BY period

SELECT strftime('%Y-%m', report_date) as period, COUNT(*) as cnt
FROM case_info


        AND syndrome_type = #{syndromeType}


        AND district = #{district}


        AND report_date >= date('now', '-' || #{days} || ' days')


GROUP BY period ORDER BY period

choose.otherwise:
SELECT report_date as period, COUNT(*) as cnt
FROM case_info


        AND syndrome_type = #{syndromeType}


        AND district = #{district}


        AND report_date >= date('now', '-' || #{days} || ' days')


GROUP BY report_date ORDER BY report_date

mapper.select:
SELECT district as name, COUNT(*) as value FROM case_info


        AND syndrome_type = #{syndromeType}


        AND district = #{district}


        AND report_date >= date('now', '-' || #{days} || ' days')


GROUP BY district ORDER BY value DESC

SELECT CASE WHEN age < 18 THEN '0-17岁' WHEN age < 45 THEN '18-44岁' WHEN age < 60 THEN '45-59岁' ELSE '60岁以上' END as name, COUNT(*) as value FROM case_info
WHERE syndrome_type = #{syndromeType}
GROUP BY name

SELECT gender as name, COUNT(*) as value FROM case_info

    WHERE syndrome_type = #{syndromeType}

GROUP BY gender

SELECT occupation as name, COUNT(*) as value FROM case_info

    WHERE syndrome_type = #{syndromeType}

GROUP BY occupation ORDER BY value DESC
